/**
 * Golden replays generated by tools/gen_golden.py from the Python research
 * prototype (the oracle). Every ply checks: legal-action count, digest of the
 * full ordered legal list, SHA-256 of canonical state bytes after the action;
 * and at the end: outcome, final digest, board, seals, counters, repetition count.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { Game, internal } from '../src/rules/index.ts';
import { initialPosition } from '../src/rules/position.ts';

interface GoldenGame {
  id: number; seed: number; first: string; second: string;
  actions: number[]; legalCounts: number[]; legalDigests: string[]; digests: string[];
  winner: number; reason: string; finalPly: number; finalQuiet: number; finalSeals: number[];
  finalBoard: number[]; finalDigest: string; finalRepetitionCount: number;
}
const golden = JSON.parse(readFileSync(new URL('../fixtures/golden_replays_v0.1.json', import.meta.url), 'utf8')) as {
  meta: { initialDigest: string; rulesVersion: string; reasonCounts: Record<string, number>; castCount: number };
  games: GoldenGame[];
};

describe('golden replays from the Python prototype', () => {
  it('fixture covers at least 100 games, all draw reasons and Concords', () => {
    expect(golden.meta.rulesVersion).toBe('ember-six/0.1');
    expect(golden.games.length).toBeGreaterThanOrEqual(100);
    for (const r of ['royal-capture', 'repetition', 'quiet-limit', 'ply-cap']) expect(golden.meta.reasonCounts[r]).toBeGreaterThan(0);
    expect(golden.meta.castCount).toBeGreaterThan(0);
    expect(Game.initial().digest()).toBe(golden.meta.initialDigest);
  });

  it.each(golden.games.map((g) => [g.id, `${g.first} v ${g.second} seed ${g.seed} -> ${g.reason}`, g] as const))(
    'game %i: %s',
    (_id, _label, gg) => {
      let g = Game.initial();
      for (let i = 0; i < gg.actions.length; i++) {
        expect(g.outcome).toBeNull();
        const codes = g.legalActions().map(internal.encodeAction);
        expect(codes.length).toBe(gg.legalCounts[i]);
        expect(internal.actionListDigest(codes).slice(0, 16)).toBe(gg.legalDigests[i]);
        const r = g.play(internal.decodeAction(gg.actions[i]!));
        if (!r.ok) throw new Error(`ply ${i}: ${r.error.message}`);
        g = r.value;
        expect(g.digest().slice(0, 16)).toBe(gg.digests[i]);
      }
      expect(g.outcome).toEqual({ winner: gg.winner, reason: gg.reason });
      expect(g.digest()).toBe(gg.finalDigest);
      const p = g.position();
      expect(p.board).toEqual(gg.finalBoard);
      expect(p.seals).toEqual(gg.finalSeals);
      expect(p.quietPly).toBe(gg.finalQuiet);
      expect(p.totalPly).toBe(gg.finalPly);
      expect(g.repetitionCount()).toBe(gg.finalRepetitionCount);
      expect(g.legalActions()).toEqual([]);
      // record round trip of a complete game
      const again = Game.fromRecord(g.toRecord());
      expect(again.ok && again.value.digest()).toBe(gg.finalDigest);
    },
  );

  it('internal make/unmake replays every golden game and restores the start exactly', () => {
    for (const gg of golden.games) {
      const p = initialPosition();
      const start = internal.clonePosition(p);
      const undos = gg.actions.map((c) => internal.makeUnchecked(p, c));
      expect(internal.positionDigest(p)).toBe(gg.finalDigest);
      for (let i = undos.length - 1; i >= 0; i--) internal.unmakeUnchecked(p, undos[i]!);
      expect(internal.positionsEqual(p, start)).toBe(true);
    }
  });
});
